PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64
// Specialized 3D convolution:
//   input  : (16, 3, 64, 64, 64) float32, contiguous
//   weight : (64, 3, 3, 3, 3)   float32, contiguous
//   bias   : (64,) float32 (optional, guarded by has_bias)
//   output : (16, 64, 62, 62, 62) float32, contiguous
// stride=1, padding=0, dilation=1, groups=1, kernel=3x3x3.
//
// Optimization: register blocking over output channels. Each CTA now
// computes 4 output channels for the same 8x8x8 spatial tile, so the
// staged input tile (3 x 10 x 10 x 10 floats in shared memory) is
// amortized across 4 accumulators per thread instead of 1, cutting
// global input-tile traffic by 4x.
// Grid  : (8, 8, 2048)  -> x/y tiles of 8, z-dim packs (ztile, oc_group, n)
// Block : (8, 8, 8)     -> 512 threads, 4 output voxels per thread
// Shared: s_in = 3 * 10 * 10 * 10 floats (tile + halo), s_w = 4 * 81 floats.
.visible .entry conv3d_kernel(
    .param .u64 in_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 out_ptr,
    .param .u32 has_bias
)
