    .reg .pred %p<16>;
    .reg .b32  %r<64>;
    .reg .b64  %rd<16>;
    .reg .f32  %f<16>;
    .shared .align 4 .b8 s_in[12000];
    .shared .align 4 .b8 s_w[1296];
    ld.param.u64 %rd1, [in_ptr];
    ld.param.u64 %rd2, [w_ptr];
    ld.param.u64 %rd3, [b_ptr];
    ld.param.u64 %rd4, [out_ptr];
    ld.param.u32 %r50, [has_bias];
    mov.u32 %r1, %tid.x;        // tx
    mov.u32 %r2, %tid.y;        // ty
    mov.u32 %r3, %tid.z;        // tz
    mov.u32 %r4, %ctaid.x;      // bx
    mov.u32 %r5, %ctaid.y;      // by
    mov.u32 %r6, %ctaid.z;      // bz
    // tid = tx + 8*ty + 64*tz
    shl.b32 %r7, %r2, 3;
    add.s32 %r7, %r7, %r1;
    shl.b32 %r8, %r3, 6;
    add.s32 %r7, %r7, %r8;
    // decompose ctaid.z: ztile = bz & 7, ocg = (bz >> 3) & 15, n = bz >> 7
    and.b32 %r9, %r6, 7;
    shr.u32 %r10, %r6, 3;
    and.b32 %r11, %r10, 15;
    shr.u32 %r12, %r10, 4;
    // tile bases
    shl.b32 %r13, %r4, 3;       // x base
    shl.b32 %r14, %r5, 3;       // y base
    shl.b32 %r15, %r9, 3;       // z base
    // output coords
    add.s32 %r16, %r13, %r1;    // ox
    add.s32 %r17, %r14, %r2;    // oy
    add.s32 %r18, %r15, %r3;    // oz
    // shared base addresses
    mov.u32 %r19, s_in;
    mov.u32 %r20, s_w;
    // ---- load weights for 4 output channels: tid < 324 ----
    setp.lt.u32 %p1, %r7, 324;
    @!%p1 bra W_DONE;
    div.u32 %r21, %r7, 81;      // j (0..3)
    mul.lo.s32 %r22, %r21, 81;
    sub.s32 %r22, %r7, %r22;    // k
    shl.b32 %r23, %r11, 2;      // oc_base = ocg*4
    add.s32 %r23, %r23, %r21;   // oc
    mul.lo.s32 %r23, %r23, 81;
    add.s32 %r23, %r23, %r22;
    mul.wide.s32 %rd5, %r23, 4;
    add.s64 %rd5, %rd2, %rd5;
    ld.global.f32 %f1, [%rd5];
    shl.b32 %r24, %r7, 2;
    add.s32 %r24, %r20, %r24;
    st.shared.f32 [%r24], %f1;
W_DONE:
    // ---- load input tile (3 x 10 x 10 x 10 = 3000 floats) ----
    mov.u32 %r23, %r7;          // idx = tid, stride 512
IN_LOOP:
    setp.lt.u32 %p2, %r23, 3000;
    @!%p2 bra IN_DONE;
    div.u32 %r24, %r23, 1000;   // ic
    mul.lo.s32 %r25, %r24, 1000;
    sub.s32 %r25, %r23, %r25;   // rem
    div.u32 %r26, %r25, 100;    // iz
    mul.lo.s32 %r27, %r26, 100;
    sub.s32 %r27, %r25, %r27;   // rem2
    div.u32 %r28, %r27, 10;     // iy
    mul.lo.s32 %r29, %r28, 10;
    sub.s32 %r29, %r27, %r29;   // ix
    add.s32 %r30, %r13, %r29;   // gx
    add.s32 %r31, %r14, %r28;   // gy
    add.s32 %r32, %r15, %r26;   // gz
    mov.f32 %f2, 0f00000000;
