    setp.lt.u32 %p3, %r30, 64;
    setp.lt.u32 %p4, %r31, 64;
    setp.lt.u32 %p5, %r32, 64;
    and.pred %p6, %p3, %p4;
    and.pred %p6, %p6, %p5;
    @!%p6 bra ST_IN;
    // in offset = ((n*3 + ic)*64 + gz)*4096 + gy*64 + gx
    mul.lo.s32 %r33, %r12, 3;
    add.s32 %r33, %r33, %r24;
    shl.b32 %r33, %r33, 6;
    add.s32 %r33, %r33, %r32;
    shl.b32 %r33, %r33, 12;
    shl.b32 %r34, %r31, 6;
    add.s32 %r33, %r33, %r34;
    add.s32 %r33, %r33, %r30;
    mul.wide.s32 %rd6, %r33, 4;
    add.s64 %rd6, %rd1, %rd6;
    ld.global.f32 %f2, [%rd6];
ST_IN:
    shl.b32 %r35, %r23, 2;
    add.s32 %r35, %r19, %r35;
    st.shared.f32 [%r35], %f2;
    add.s32 %r23, %r23, 512;
    bra IN_LOOP;
IN_DONE:
    bar.sync 0;
    // ---- skip compute for out-of-range output voxels ----
    setp.lt.u32 %p7, %r16, 62;
    setp.lt.u32 %p8, %r17, 62;
    setp.lt.u32 %p9, %r18, 62;
    and.pred %p10, %p7, %p8;
    and.pred %p10, %p10, %p9;
    @!%p10 bra K_END;
    // tin_base = tz*100 + ty*10 + tx
    mul.lo.s32 %r36, %r3, 100;
    mul.lo.s32 %r37, %r2, 10;
    add.s32 %r36, %r36, %r37;
    add.s32 %r36, %r36, %r1;
    mov.u32 %r46, 0;            // j (0..3): output-channel register block
OC_LOOP:
    setp.lt.u32 %p15, %r46, 4;
    @!%p15 bra OC_DONE;
    mov.f32 %f3, 0f00000000;    // acc
    // per-j weight base: s_w + j*81 floats (j*324 bytes)
    mul.lo.s32 %r47, %r46, 324;
    add.s32 %r47, %r47, %r20;
    mov.u32 %r38, 0;            // ic
IC_LOOP:
    setp.lt.u32 %p11, %r38, 3;
    @!%p11 bra IC_DONE;
    mov.u32 %r39, 0;            // kz
KZ_LOOP:
    setp.lt.u32 %p12, %r39, 3;
    @!%p12 bra KZ_DONE;
    mov.u32 %r40, 0;            // ky
KY_LOOP:
    setp.lt.u32 %p13, %r40, 3;
    @!%p13 bra KY_DONE;
    // &s_in[ic*1000 + (tz+kz)*100 + (ty+ky)*10 + tx]
    mul.lo.s32 %r41, %r38, 1000;
    mul.lo.s32 %r42, %r39, 100;
    add.s32 %r41, %r41, %r42;
    mul.lo.s32 %r42, %r40, 10;
    add.s32 %r41, %r41, %r42;
    add.s32 %r41, %r41, %r36;
    shl.b32 %r41, %r41, 2;
    add.s32 %r41, %r19, %r41;
    // &s_w[j*81 + ic*27 + kz*9 + ky*3]
    mul.lo.s32 %r42, %r38, 27;
    mul.lo.s32 %r43, %r39, 9;
    add.s32 %r42, %r42, %r43;
    mul.lo.s32 %r43, %r40, 3;
    add.s32 %r42, %r42, %r43;
    shl.b32 %r42, %r42, 2;
    add.s32 %r42, %r47, %r42;
    // unrolled kx = 0, 1, 2
    ld.shared.f32 %f4, [%r41];
    ld.shared.f32 %f5, [%r42];
    fma.rn.f32 %f3, %f4, %f5, %f3;
    ld.shared.f32 %f4, [%r41+4];
    ld.shared.f32 %f5, [%r42+4];
    fma.rn.f32 %f3, %f4, %f5, %f3;
    ld.shared.f32 %f4, [%r41+8];
    ld.shared.f32 %f5, [%r42+8];
    fma.rn.f32 %f3, %f4, %f5, %f3;
    add.s32 %r40, %r40, 1;
    bra KY_LOOP;
KY_DONE:
    add.s32 %r39, %r39, 1;
    bra KZ_LOOP;
KZ_DONE:
    add.s32 %r38, %r38, 1;
    bra IC_LOOP;
IC_DONE:
    // oc = ocg*4 + j
    shl.b32 %r48, %r11, 2;
    add.s32 %r48, %r48, %r46;
    // optional bias add
    setp.eq.u32 %p14, %r50, 0;
    @%p14 bra B_DONE;
    mul.wide.s32 %rd7, %r48, 4;
    add.s64 %rd7, %rd3, %rd7;
    ld.global.f32 %f6, [%rd7];
    add.f32 %f3, %f3, %f6;
B_DONE:
    // out offset = (((n*64 + oc)*62 + oz)*62 + oy)*62 + ox
    shl.b32 %r44, %r12, 6;
    add.s32 %r44, %r44, %r48;
    mul.lo.s32 %r44, %r44, 62;
    add.s32 %r44, %r44, %r18;
    mul.lo.s32 %r44, %r44, 62;
    add.s32 %r44, %r44, %r17;
    mul.lo.s32 %r44, %r44, 62;
    add.s32 %r44, %r44, %r16;
    mul.wide.s32 %rd8, %r44, 4;
    add.s64 %rd8, %rd4, %rd8;
    st.global.f32 [%rd8], %f3;
    add.s32 %r46, %r46, 1;
