    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.conv3d = nn.Conv3d(in_channels, out_channels, (kernel_size, kernel_size, kernel_size), stride=stride, padding=padding, dilation=dilation, groups=groups, bias=bias)
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        weight = self.conv3d.weight
        if not x.is_contiguous():
            x = x.contiguous()
        if not weight.is_contiguous():
            weight = weight.contiguous()
        n, ic, d, h, w = x.shape
        oc = weight.shape[0]
        assert x.is_cuda and x.dtype == torch.float32
        assert (n, ic, d, h, w) == (16, 3, 64, 64, 64) and oc == 64
        out = torch.empty((16, 64, 62, 62, 62), device=x.device, dtype=x.dtype)
        bias = self.conv3d.bias
        if bias is not None:
            bias_arg = bias.contiguous()
            has_b = 1
        else:
            bias_arg = weight
            has_b = 0
        module = _get_ptx_module()
        module.launch(
            "conv3d_kernel",
            grid=(8, 8, 2048),
            block=(8, 8, 8),
            arguments=[x, weight, bias_arg, out, u32(has_b)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

